sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    /*
        To maintain path from parent to a selected node 
        ex. if tree is 1 -> 2 -> 3 and 3 is selected 
            then path is [1, 2, 3]
    */
    let path = [];
    /*
        To maintain every node's path from parent to selected node
        ex. if tree is 1 -> 2 -> 3 and 3 is expanded 
            then expandedPath is [[1], [1, 2], [1, 2, 3]]
    */
    let expandedPath = [];
    const root = api.data.get_goalstargets_tree.output[0];
    const id = api.context.props.sysId;

    getPath(root, id, path, expandedPath);

    api.setState('selectedItem', [path]);
    api.setState('expandedItem', expandedPath);

    function getPath(node, id, path, expandedPath) {
        if (!node)
            return false;

        path.push(node.id);
        expandedPath.push([...path]);

        if (node.id == id)
            return true;
        if (node.children) {
            for (let i = 0; i < node.children.length; i++) {
                if (getPath(node.children[i], id, path, expandedPath))
                    return true;
            }
        }
        expandedPath.pop();
        path.pop();
        return false;
    }
}
